# Terraform Module: S3 + RDS + IAM

## Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
├── backend.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
└── modules/
    ├── s3_bucket/
    ├── rds/
    └── iam_role/
```

---

## Root

### `providers.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}
```

### `backend.tf`

```hcl
terraform {
  backend "s3" {
    bucket         = "mycompany-tfstate"
    key            = "app/terraform.tfstate"
    dynamodb_table = "tf-locks"
    encrypt        = true
  }
}
```

### `variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev | prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "project" {
  type    = string
  default = "myapp"
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_allocated_storage" {
  type = number
}

variable "replication_region" {
  description = "Destination region for bucket replication (prod only). null disables."
  type        = string
  default     = null
}

variable "db_password" {
  description = "Provided via SOPS-decrypted tfvars or env var — never committed"
  type        = string
  sensitive   = true
}

variable "oidc_provider_url" {
  description = "EKS OIDC issuer URL for IRSA trust"
  type        = string
  default     = null
}

variable "oidc_namespace" {
  type    = string
  default = "default"
}

variable "oidc_service_account" {
  type    = string
  default = "app-sa"
}
```

### `main.tf`

```hcl
module "s3_bucket" {
  source = "./modules/s3_bucket"

  name               = "${var.project}-${var.environment}-assets"
  replication_region = var.replication_region
  tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }
}

module "rds" {
  source = "./modules/rds"

  identifier          = "${var.project}-${var.environment}"
  instance_class      = var.db_instance_class
  multi_az            = var.db_multi_az
  allocated_storage   = var.db_allocated_storage
  password            = var.db_password
  deletion_protection = true
  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

module "iam_role" {
  source = "./modules/iam_role"

  name                  = "${var.project}-${var.environment}-sa-role"
  oidc_provider_url     = var.oidc_provider_url
  oidc_namespace        = var.oidc_namespace
  oidc_service_account  = var.oidc_service_account
  bucket_arn            = module.s3_bucket.bucket_arn
  restrict_to_bucket    = true
  tags = {
    Environment = var.environment
  }
}
```

### `outputs.tf`

```hcl
output "bucket_name" {
  value = module.s3_bucket.bucket_name
}

output "bucket_arn" {
  value = module.s3_bucket.bucket_arn
}

output "db_endpoint" {
  value = module.rds.endpoint
}

output "db_connection_string" {
  value     = "postgresql://${module.rds.username}:${var.db_password}@${module.rds.endpoint}/${module.rds.db_name}"
  sensitive = true
}

output "service_account_role_arn" {
  value = module.iam_role.role_arn
}
```

---

## Module: `modules/s3_bucket/`

### `variables.tf`

```hcl
variable "name" { type = string }
variable "replication_region" { type = string, default = null }
variable "tags" { type = map(string), default = {} }
```

### `main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod)
resource "aws_s3_bucket" "replica" {
  count  = var.replication_region != null ? 1 : 0
  provider = aws.replica
  bucket = "${var.name}-replica"
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count   = var.replication_region != null ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication" {
  count = var.replication_region != null ? 1 : 0
  name  = "${var.name}-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_region != null ? 1 : 0
  name  = "replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count     = var.replication_region != null ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.this]
  role       = aws_iam_role.replication[0].arn
  bucket     = aws_s3_bucket.this.id

  rule {
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}
```

### `outputs.tf`

```hcl
output "bucket_name" { value = aws_s3_bucket.this.id }
output "bucket_arn"  { value = aws_s3_bucket.this.arn }
```

*(Also add `provider "aws" { alias = "replica" region = var.replication_region }` and pass `replica` provider via module `providers` block, or use `aws.replica` as shown.)*

---

## Module: `modules/rds/`

### `main.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.identifier}-db-subnets"
  subnet_ids = var.subnet_ids
  tags       = var.tags
}

resource "aws_security_group" "this" {
  name   = "${var.identifier}-db"
  vpc_id = var.vpc_id
  tags   = var.tags

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "this" {
  identifier     = var.identifier
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.allocated_storage * 2
  storage_encrypted     = true

  db_name  = var.db_name
  username = var.username
  password = var.password

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.this.id]
  multi_az               = var.multi_az
  publicly_accessible    = false

  deletion_protection      = var.deletion_protection
  backup_retention_period  = 7
  skip_final_snapshot      = false
  final_snapshot_identifier = "${var.identifier}-final"
}
```

### `variables.tf`

```hcl
variable "identifier"        { type = string }
variable "instance_class"    { type = string }
variable "allocated_storage" { type = number }
variable "multi_az"          { type = bool }
variable "deletion_protection" { type = bool }
variable "password"          { type = string, sensitive = true }
variable "db_name"           { type = string, default = "appdb" }
variable "username"          { type = string, default = "appuser" }
variable "vpc_id"            { type = string }
variable "subnet_ids"        { type = list(string) }
variable "allowed_security_groups" { type = list(string), default = [] }
variable "tags"              { type = map(string), default = {} }
```

### `outputs.tf`

```hcl
output "endpoint"  { value = aws_db_instance.this.address }
output "db_name"   { value = aws_db_instance.this.db_name }
output "username"  { value = aws_db_instance.this.username }
```

---

## Module: `modules/iam_role/`

### `main.tf`

```hcl
data "aws_iam_policy_document" "trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(var.oidc_provider_url, "https://", "")}"]
    }

    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_url, "https://", "")}:sub"
      values   = ["system:serviceaccount:${var.oidc_namespace}:${var.oidc_service_account}"]
    }
  }
}

data "aws_iam_policy_document" "least_privilege" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
    ]
    resources = var.restrict_to_bucket
      ? [var.bucket_arn, "${var.bucket_arn}/*"]
      : ["*"] # dev only
  }
}

resource "aws_iam_role" "this" {
  name               = var.name
  assume_role_policy = data.aws_iam_policy_document.trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "this" {
  name   = "${var.name}-policy"
  role   = aws_iam_role.this.id
  policy = data.aws_iam_policy_document.least_privilege.json
}
```

### `outputs.tf`

```hcl
output "role_arn" { value = aws_iam_role.this.arn }
```

---

## Environment configs

### `environments/dev.tfvars`

```hcl
environment        = "dev"
aws_region         = "us-east-1"
db_instance_class  = "db.t3.micro"
db_multi_az        = false
db_allocated_storage = 20
replication_region = null
```

### `environments/prod.tfvars`

```hcl
environment        = "prod"
aws_region         = "us-east-1"
db_instance_class  = "db.t3.medium"
db_multi_az        = true
db_allocated_storage = 50
replication_region = "us-west-2"
```

DB password is supplied at plan/apply time from SOPS: `sops -d secrets/prod.yaml > /tmp/prod-secrets.tfvars && terraform apply -var-file=environments/prod.tfvars -var-file=/tmp/prod-secrets.tfvars`

---

## Usage (workspaces)

```bash
terraform workspace new dev
terraform workspace select dev
terraform init
terraform apply -var-file=environments/dev.tfvars -var="db_password=$DB_PASSWORD"

terraform workspace select prod
terraform apply -var-file=environments/prod.tfvars -var="db_password=$(sops -d --extract '["db_password"]' secrets/prod.yaml)"
```

**Isolation note:** with a single S3 backend, use `key = "app/${terraform.workspace}/terraform.tfstate"` (or a `prefix` in the backend config) so dev/prod state files are fully separate — changing prod never touches dev state.

## Acceptance criteria mapping

- ✅ Bucket: versioning, SSE-KMS with bucket key, public access blocked, replication in prod
- ✅ RDS: deletion protection, 7-day backups, encrypted storage, `publicly_accessible = false`
- ✅ Secret: passed as sensitive var from SOPS, never committed
- ✅ IAM: OIDC-trust role scoped to one service account, actions limited to specific S3 ops (no wildcards on prod)
- ✅ Environments: separate tfvars + workspaces/state keys → independent deployability
